export function BrandMark({
  className,
  tone = "auto",
}: {
  brand?: BrandConfig;
  className?: string;
  accentClassName?: string;
  showMark?: boolean;
  tone?: Tone;
}) {
  const color =
    tone === "dark" ? "#17baa8" : tone === "light" ? "#0c6e63" : "var(--accent)";
  return (
    <span
      className={cn("brand-mark inline-flex items-center leading-none", className)}
      data-tone={tone}
      style={{ color }}
      role="img"
      aria-label="OneStreet"
    >
      <img
        src="/brand/logo-light.png"
        alt=""
        width={1292}
        height={331}
        className="brand-logo-light"
        draggable={false}
      />
      <svg className="brand-wordmark" viewBox="0 0 4383 724" aria-hidden="true">
        <path fill="currentColor" d={WORDMARK} />
      </svg>
    </span>
  );
}
